class Program {
    static async HttpResponse Handle(HttpRequest req) {
        if (req.method == "GET" && req.path == "/health") {
            return HttpResponse.Text("ok");
        }
        if (req.method == "GET" && req.path == "/users") {
            return HttpResponse.Json("[{\"id\":1,\"name\":\"alice\"}]");
