using System.Net.Http;
using System.Json;

static async HttpResponse CreateTodo(HttpRequest req) {
    JsonValue doc = JsonValue.ParseLenient(req.body);
    string title = doc.Str("title", "");
    if (title.Length == 0) {
        HttpResponse bad = HttpResponse.Json("{\"error\":\"title required\"}");
        bad.statusCode = 400;
        bad.statusText = "Bad Request";
        return bad;
    }

    JsonValue item = JsonValue.NewObject();
    item.Set("id", JsonValue.NewNum("1"));
    item.Set("title", JsonValue.NewStr(title));
    item.Set("done", JsonValue.NewBool(false));

    HttpResponse res = HttpResponse.Json(item.ToJson());
    res.statusCode = 201;
    res.statusText = "Created";
    return res;
}

