using System;
using System.Net.Sockets;
using System.Net.Sse;

class Program {
    static async int Run() {
        Socket.Initialize();
        SseServer srv = new SseServer("0.0.0.0", 8090);
        srv.Start();

        List<SseConnection> subs = new List<SseConnection>();
        SseConnection c = await srv.AcceptAsync();
        if (c != null) {
            Console.WriteLine("subscriber on " + c.Path());
            subs.Add(c);
        }

        for (int tick = 0; tick < 3; tick++) {
            foreach (SseConnection s in subs) {
                int _n = await s.SendAsync("price",
                    "{\"symbol\":\"ZAN\",\"px\":" + Convert.ToString(100 + tick) + "}");
            }
            await Task.Delay(1000);
        }

        foreach (SseConnection s in subs) {
            int _p = await s.PingAsync();     // keep-alive comment line
            s.Close();                        // client's NextAsync returns null
        }
        srv.Stop();
        return 0;
    }

    static void Main() { int r = await Run(); }
}

