        Socket.Initialize();
        SseClient c = await SseClient.ConnectAsync("127.0.0.1", 8090, "/stream");
        if (!c.IsConnected()) { Console.WriteLine("subscribe failed"); return 1; }

        while (true) {
            SseEvent e = await c.NextAsync();
            if (e == null) { break; }        // stream closed
            Console.WriteLine(e.Name() + ": " + e.Data());
        }
        c.Close();
        return 0;
    }

    static void Main() { int r = await Run(); }
}

using System;
using System.Net.Sockets;
using System.Net.WebSocket;

class Program {
    static async int Run() {
        Socket.Initialize();
        WebSocketClient c = await WebSocketClient.ConnectAsync(
            "127.0.0.1", 8080, "/chat");
        if (!c.IsConnected()) { Console.WriteLine("handshake failed"); return 1; }

        await c.SendText("hello");
        string reply = await c.RecvText();
        Console.WriteLine("got: " + reply);

        await c.Ping();       // heartbeat, server answers with pong
        await c.Close();      // close frame, then TCP shutdown
        return 0;
    }

    static void Main() { int r = await Run(); }
}

