using System;
using System.Net.Sockets;

class Program {
    static async void HandleClient(nint sock) {
        TcpClient c = TcpClient.FromSocket(sock);
        string buf = "";
        while (true) {
            string chunk = await c.RecvAsync(4096);
            if (chunk.Length == 0) { break; }      // peer closed
            buf = buf + chunk;

            int nl = buf.IndexOf("\n");
            while (nl >= 0) {
                string line = buf.Substring(0, nl);
                buf = buf.Substring(nl + 1, buf.Length - nl - 1);
                int _n = await c.SendAsync("echo: " + line + "\n");
                nl = buf.IndexOf("\n");
            }
        }
        c.Close();
    }

    static async int Run() {
        Socket.Initialize();
        TcpListener listener = new TcpListener("0.0.0.0", 9000);
        listener.Start();
        while (true) {
            nint sock = await listener.AcceptAsync();
            if (sock >= 0) { Task.Spawn(HandleClient(sock)); }
        }
        return 0;
    }

    static void Main() { int r = await Run(); }
}

