static async string UserName(RedisClient r, int id) {
    string key = "user:" + Convert.ToString(id) + ":name";
    string cached = await r.GetAsync(key);
    if (cached != null) { return cached; }

    string fresh = LoadFromDb(id);          // cache miss: go to the database
    bool ok = await r.SetAsync(key, fresh);
    int e = await r.ExpireAsync(key, 60);   // expire in 60s
    return fresh;
}

